"""Juniper Switch"""
from __future__ import print_function
from builtins import str
from builtins import range
import time
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.networking_devices.switch.SshConnection import SshConnection
from taf.ul.trs_e2e_fw.lib.utils.string_format import decode_str

logger = BackgroundLogger.Instance()


class JuniperSsh(SshConnection):
    """Juniper switch"""
    TOOL = "juniper"

    def __init__(self, device, command_profile):
        """
        This methods does following :
        1. calls the parent class init method using the super.
        2. Initializes show_command for the object called.
        Args:
            device: Section name in switch in testline config file
            command_profile: Command profile name, from the switch sestion of the testline config file.

        Returns: this method is not supposed to return anything.

        """

        super(JuniperSsh, self).__init__(device, command_profile)
        self.cli_prompt_char = ">"
        self.configure_prompt_char = "#"
        self.unix_prompt_char = "%"

    def execute_commands_and_verify(self):
        self._ssh_execute_command('cli', self.cli_prompt_char)
        self._ssh_execute_command('configure', self.configure_prompt_char)
        commands_list = self.command_profile
        for each_command in commands_list:
            self._ssh_execute_command(each_command, self.configure_prompt_char)
        self._ssh_execute_command('exit', self.cli_prompt_char)
        self._ssh_execute_command('exit', self.unix_prompt_char)

    def _ssh_execute_command(self, command, prompt=None, timeout=30):
        """

        Execute commands on swicth

        Args:
            command (str): command to be executed
            prompt (str): switch prompt

        Returns:
            None

        Raises:
            Exception: Raised when failed to execute command

        """
        try:
            if prompt is None:
                prompt = self.cli_prompt_char
            logger.info("Executor command : " + command)
            self.ssh_shell.send(command + "\n")
            for i in range(timeout):
                output = self.ssh_shell.recv(65535)
                if prompt in decode_str(output):
                    logger.info("Executor Output : {} ".format(str(output)))
                    return decode_str(output)
                time.sleep(1)
            logger.error("Command execution failed as expected prompt did not appear in output")
        except Exception as err:
            pass
            logger.error("{} Command execution failed : {}".format(command, err))
